before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <future>
#include <iostream>
#include <stdexcept>
int calculate(bool fail) {
    if (fail) throw std::runtime_error("calculation failed");
    return 6 * 7;
}
int main() {
    auto result = std::async(std::launch::async, calculate, false);
    try {
        std::cout << result.get() << "\n";
    } catch (const std::runtime_error& error) {
        std::cout << error.what() << "\n";
    }
}
```

after:
Follow the calculation into the future and then through get().

```cpp
#include <future>
#include <iostream>
#include <stdexcept>
int calculate(bool fail) {
    if (fail) throw std::runtime_error("calculation failed");
    return 6 * 7;
}
int main() {
    auto result = std::async(std::launch::async, calculate, false);
    try {
        std::cout << result.get() << "\n";
    } catch (const std::runtime_error& error) {
        std::cout << error.what() << "\n";
    }
}
```
